export function legalPath(lang: string, kind: LegalKind) {
  if (!noticeCopy[lang]) throw new Error(`Unsupported notice locale ${lang}`);
  if (kind === 'ai') return aiUsePath(lang);
  const segment = kind === 'privacy' ? 'privacy' : kind === 'cookies' ? 'cookie-policy' : lang === 'it' ? 'uso-intelligenza-artificiale' : 'ai-transparency';
  return `${lang === 'it' ? '' : `/${lang}`}/${segment}`;
}
