for (const [locale, decision] of Object.entries(ownerDecisions)) {
  const copy = noticeCopy[locale];
  if (locale === 'pt') copy.cookies = 'Política de cookies e preferências';
  copy.pending = `${copy.privacy} · 2026-11-25`;
  copy.privacyText = [copy.privacyText[0], copy.privacyText[1], decision.storage,
    decision.providers, decision.retention, copy.privacyText[5]];
  copy.cookieText = [copy.cookieText[0], decision.cookies, ...(cookieInventory[locale] ? [cookieInventory[locale]] : [])];
  // Index 3 was an internal delivery note (owner review still to document), not visitor information.
  copy.aiText = [decision.illustrative, ...copy.aiText.filter((_, index) => index !== 3)];
  copy.footer = copy.footer.split(/(?<=\.)\s/)[0];
}
